import {readFile,writeFile,mkdir,stat} from 'node:fs/promises';
import {createRequire} from 'node:module';
import {createHash} from 'node:crypto';
import path from 'node:path';
const root=process.cwd(), require=createRequire(path.join(root,'projects/site/package.json')),sharp=require('sharp');
const out=path.join(root,'outputs/independent-article-images-20261126');
const manifestPath=path.join(root,'kb/research/stories/independent-features/images.json');
const manifest=JSON.parse(await readFile(manifestPath)),plan=JSON.parse(await readFile(path.join(out,'image-production-plan.json')));
const digest=b=>createHash('sha256').update(b).digest('hex');
async function saveNew(p,b){await mkdir(path.dirname(p),{recursive:true});try{const old=await readFile(p);if(!old.equals(b))throw Error('Refusing to overwrite different asset '+p);}catch(e){if(e.code!=='ENOENT')throw e;await writeFile(p,b);}}
const results=[];
for(const item of plan){
 const input=await readFile(path.join(root,item.input)),m=manifest[item.slug],meta=await sharp(input).metadata();
 const r={slug:item.slug,input:item.input,input_sha256:digest(input),input_bytes:input.length,reused:item.reuse,outputs:[]};
 if(item.reuse){m.width=meta.width;m.height=meta.height;r.outputs.push({src:m.src,width:m.width,height:m.height,bytes:input.length,sha256:digest(input),existing:true});}
 else{
  const {data,info}=await sharp(input).rotate().resize({width:1200,height:1200,fit:'inside',withoutEnlargement:true}).webp({quality:80,effort:6}).toBuffer({resolveWithObject:true});
  await writeFile(path.join(root,'projects/site/public',m.src),data);m.width=info.width;m.height=info.height;
  r.outputs.push({src:m.src,width:info.width,height:info.height,bytes:data.length,sha256:digest(data)});
  const small=await sharp(input).rotate().resize({width:480,height:480,fit:'inside',withoutEnlargement:true}).webp({quality:76,effort:6}).toBuffer({resolveWithObject:true});
  m.small_src=m.src.replace('-v1.webp','-480-v1.webp');m.small_width=small.info.width;m.small_height=small.info.height;
  await writeFile(path.join(root,'projects/site/public',m.small_src),small.data);
  r.outputs.push({src:m.small_src,width:small.info.width,height:small.info.height,bytes:small.data.length,sha256:digest(small.data)});
 }
 results.push(r);
}
await writeFile(manifestPath,JSON.stringify(manifest,null,2)+'\n');
await writeFile(path.join(out,'image-production-report.json'),JSON.stringify({transform:'Aspect-preserving downsize: primary within1200x1200 at WebP quality80; previews within480x480 at quality76. No crop, retouch or content alteration. Source images and earlier quality84 derivatives retained.',results},null,2)+'\n');
console.log(JSON.stringify({articles:results.length,reused:results.filter(x=>x.reused).length,new_assets:results.filter(x=>!x.reused).flatMap(x=>x.outputs).length,new_bytes:results.filter(x=>!x.reused).flatMap(x=>x.outputs).reduce((n,x)=>n+x.bytes,0)}));
